@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Press+Start+2P&display=swap');
:root{--ink:#193b36;--muted:#77918a;--green:#316e57;--lime:#c8e982;--paper:#f5f5e9;--line:#dfe6d9;--serif:#fafaf3}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#e8eee1;color:var(--ink);font-family:'DM Sans',sans-serif}body{min-height:100dvh;background:radial-gradient(ellipse at 48% 35%,#f4f4e9 0,#e6ecdf 80%)}button{font:inherit}.app-shell{max-width:1440px;margin:auto;min-height:100dvh;padding:0 40px;display:flex;flex-direction:column}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d5dfd2}.brand{display:flex;align-items:center;gap:11px;color:#244a3c;font-size:13px;font-weight:800;letter-spacing:2.2px;text-decoration:none}.brand-mark{background:#356e56;color:#d9f09e;width:29px;height:29px;display:grid;place-items:center;border-radius:9px;font-size:17px;box-shadow:0 3px 0 #244c3c}.top-actions{display:flex;gap:22px;align-items:center}.save-status{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#789187}.save-status i{display:inline-block;width:6px;height:6px;background:#74a77a;border-radius:50%;margin-right:7px;box-shadow:0 0 0 3px #dcebd8}.icon-button{border:1px solid #d3ded2;background:#f6f7ed;color:#386b58;width:34px;height:34px;border-radius:10px;font-size:17px;cursor:pointer}.game-layout{display:grid;grid-template-columns:220px minmax(380px,710px) 220px;gap:30px;justify-content:center;align-items:center;flex:1;padding:26px 0}.side-panel{height:100%;min-height:390px;padding:5px 0;display:flex;flex-direction:column}.trainer-card{display:flex;align-items:center;gap:12px;padding:12px 0 22px;border-bottom:1px solid var(--line)}.trainer-avatar{width:43px;height:43px;border-radius:13px;background:#d8eab9;display:grid;place-items:center;color:#62916b;font-size:22px;border:1px solid #c8dcb1}.eyebrow,.section-label,.progress-heading{font:9px 'DM Mono',monospace;letter-spacing:1.1px;color:#789087}.trainer-card strong{display:block;font-size:12px;margin:4px 0}.trainer-card small{display:block;font:8px 'DM Mono',monospace;color:#93a49a;letter-spacing:.4px}.section-label{display:flex;justify-content:space-between;align-items:center;margin:21px 0 12px}.team-count{font-size:9px;color:#a1afa5}.party-list{display:flex;flex-direction:column;gap:8px}.party-slot{display:flex;align-items:center;gap:10px;background:#f7f8ef;border:1px solid #e1e8dc;border-radius:11px;padding:9px 10px;min-height:58px}.mini-mon{width:36px;height:36px;border-radius:10px;background:#e5efce;display:grid;place-items:center;font-size:22px}.party-name{font-size:11px;font-weight:700}.party-lv{font:8px 'DM Mono',monospace;color:#8da198;margin-top:3px}.party-hp{margin-left:auto;width:42px;height:4px;background:#e1e9dd;border-radius:4px;overflow:hidden}.party-hp i{display:block;width:100%;height:100%;background:#87b878}.journal-card{margin-top:auto;background:#edf2e4;border:1px solid #dce7d7;border-radius:12px;padding:15px 14px;color:#426650}.journal-icon{font-size:18px;color:#83a777;margin-bottom:8px}.journal-card p{font-size:11px;line-height:1.6;margin:8px 0;color:#446451;font-style:italic}.journal-line{height:1px;background:#d7e3d3;margin:10px 0}.journal-card small{font:8px 'DM Mono',monospace;color:#8ca091;letter-spacing:.7px}.play-area{min-width:0;width:100%;max-width:710px}.scene-topline{display:flex;justify-content:space-between;align-items:center;padding:0 4px 11px;font:10px 'DM Mono',monospace;letter-spacing:1.1px;color:#527365}.location-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#9abd68;margin:0 9px 0 0;box-shadow:0 0 0 3px #e1ebd4}.weather{font-size:14px;color:#d2a951}.weather span{font:9px 'DM Mono',monospace;color:#8d9b8e;margin-left:6px}.game-frame{width:100%;position:relative;overflow:hidden;border:7px solid #315c4d;border-radius:10px;background:#a5c979;box-shadow:0 8px 0 #254b3e,0 17px 35px #506e5130;image-rendering:pixelated}.game-frame:after{content:'';position:absolute;inset:0;pointer-events:none;border:1px solid #c1d49455;box-shadow:inset 0 0 22px #122e281a}#game{width:100%;height:auto;display:block;image-rendering:pixelated;image-rendering:crisp-edges}.toast{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);white-space:nowrap;max-width:90%;overflow:hidden;text-overflow:ellipsis;background:#193b36e8;color:#f5f5d9;padding:9px 14px;border:1px solid #a6bf7188;border-radius:5px;font:8px 'DM Mono',monospace;letter-spacing:.2px;box-shadow:0 3px 0 #102c27;transition:opacity .25s}.world-footer{display:flex;align-items:center;justify-content:space-between;padding:15px 4px 0}.objective{display:flex;align-items:center;gap:10px}.objective-icon{width:27px;height:27px;border-radius:8px;background:#dce9c8;display:grid;place-items:center;color:#5f9469;font-size:17px}.objective small{display:block;color:#9aa99b;font:8px 'DM Mono',monospace;letter-spacing:.6px}.objective strong{display:block;font-size:11px;margin-top:3px}.map-coords{font:9px 'DM Mono',monospace;color:#82948a;display:flex;align-items:center;gap:8px}.tiny-compass{font-size:8px;color:#799c70}.right-panel .section-label{margin-top:5px;margin-bottom:16px}.kit-spark{font-size:14px;color:#91ae69}.kit-card{display:flex;align-items:center;gap:9px;padding:10px 8px;border-bottom:1px solid #e0e7dc}.kit-item{height:33px;width:33px;border-radius:10px;display:grid;place-items:center;font-size:17px}.capsule-icon{background:#f3e5d3;color:#ca7f5a}.berry-icon{background:#f2e7d0;color:#bc8750}.kit-info{min-width:0}.kit-info strong{display:block;font-size:10px;white-space:nowrap}.kit-info small{display:block;font:8px 'DM Mono',monospace;color:#94a398;margin-top:4px}.item-count{margin-left:auto;font:10px 'DM Mono',monospace;color:#789079}.progress-card{background:#f3f5e9;border:1px solid #e1e8da;padding:13px 12px;border-radius:11px;margin-top:22px}.progress-heading{display:flex;justify-content:space-between;font-size:8px}.progress-heading span:last-child{color:#65926d}.progress-bar{height:5px;background:#e1e9d8;border-radius:5px;margin:11px 0 9px;overflow:hidden}.progress-bar i{display:block;width:0;height:100%;background:#9abf6d;transition:width .3s}.progress-card p{font-size:9px;color:#839488;line-height:1.5;margin:0}.controls-hint{margin-top:auto;display:flex;align-items:center;gap:12px;padding:13px 8px;background:#eef2e7;border-radius:11px}.hint-keyboard{width:53px;height:42px;display:grid;grid-template-columns:repeat(3,16px);grid-template-rows:repeat(2,17px);gap:2px}.hint-keyboard span{display:grid;place-items:center;background:#f9faef;border:1px solid #dbe4d7;border-radius:3px;color:#7a9584;font:9px 'DM Mono',monospace}.hint-keyboard span:first-child{grid-column:2}.hint-keyboard span:nth-child(2){grid-column:1}.hint-keyboard span:nth-child(3){grid-column:2}.hint-keyboard span:nth-child(4){grid-column:3}.controls-hint p{font-size:8px;line-height:1.7;color:#829389;margin:0}.controls-hint strong{color:#42644f}.bottom-bar{height:48px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid #d7e0d4;color:#91a095;font:8px 'DM Mono',monospace;letter-spacing:.7px}.bottom-bar b{color:#617e69}.bottom-bar i{font-style:normal;color:#bcc8bc;margin:0 7px}.footer-tip{color:#8e9c91}.footer-tip kbd{font:8px 'DM Mono',monospace;border:1px solid #c9d5c9;border-radius:3px;padding:3px 4px;color:#6b8273}.battle-overlay{position:absolute;inset:0;z-index:2;background:linear-gradient(180deg,#c8e3b4 0%,#dce8b6 49%,#b4cf88 50%,#9fbf72 100%);display:flex;flex-direction:column;align-items:center;padding:12px 16px 13px;color:#23483d}.battle-overlay.hidden{display:none}.battle-top{position:relative;z-index:1;align-self:stretch;background:#f7f6e8;border:2px solid #315c4d;border-radius:6px;padding:8px 10px;box-shadow:0 3px 0 #69855c;display:grid;grid-template-columns:1fr 40%;align-items:center}.battle-top strong{font-family:'Press Start 2P',monospace;font-size:10px;display:block;margin:7px 0 4px}.battle-top small{font:8px 'DM Mono',monospace;color:#769084}.wild-label{font:7px 'DM Mono',monospace;letter-spacing:.8px;color:#87a27b}.wild-hp{align-self:center}.hp-meta{display:flex;justify-content:space-between;font:7px 'DM Mono',monospace;color:#829386;margin-bottom:5px}.hp-track{height:7px;border-radius:5px;background:#d9e3d4;border:1px solid #9cad8c;overflow:hidden}.hp-track i{height:100%;display:block;width:100%;background:#8cba72;transition:width .3s}.hp-track i.low{background:#d39c5e}.hp-track i.critical{background:#ce765f}#battle-art{position:absolute;width:43%;height:auto;max-height:53%;top:31%;left:50%;transform:translate(-50%,-50%);image-rendering:pixelated}.battle-message{position:absolute;left:10px;right:10px;bottom:67px;min-height:30px;border:2px solid #315c4d;border-radius:5px;background:#fbfaed;padding:8px 9px;box-shadow:0 2px 0 #67805b;font:8px 'DM Mono',monospace;color:#456a54;display:flex;align-items:center}.battle-actions{position:absolute;bottom:10px;left:10px;right:10px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px}.battle-btn{border:2px solid #315c4d;border-radius:5px;background:#f8f6e8;box-shadow:0 3px 0 #68845c;color:#385c4c;min-height:35px;font:8px 'DM Mono',monospace;cursor:pointer;transition:transform .1s,box-shadow .1s}.battle-btn:hover{background:#fff}.battle-btn:active{transform:translateY(2px);box-shadow:0 1px 0 #68845c}.battle-btn span{font-size:13px;margin-right:4px;color:#76a166}.battle-btn.primary{background:#dff0bd}.battle-btn.catch{background:#f5e4d3}.battle-btn.catch span{color:#cf815d}.battle-btn b{font-size:7px;color:#9b8b73}.continue-btn{position:absolute;bottom:11px;right:12px;padding:0 12px;background:#dff0bd}.continue-btn.hidden{display:none}.mobile-controls{display:none}
@media(max-width:950px){.app-shell{padding:0 22px}.game-layout{grid-template-columns:170px minmax(340px,1fr) 170px;gap:17px}.side-panel{min-height:350px}.trainer-card strong{font-size:11px}.kit-info strong{font-size:9px}}
@media(max-width:700px){html,body{overscroll-behavior:none}.app-shell{padding:0 14px;min-height:100dvh}.topbar{height:53px}.brand{font-size:11px}.brand-mark{width:26px;height:26px}.top-actions{gap:12px}.save-status{font-size:8px}.icon-button{width:30px;height:30px}.game-layout{display:flex;flex-direction:column;gap:0;align-items:stretch;padding:10px 0 130px}.side-panel{display:none}.play-area{width:100%;max-width:none}.scene-topline{padding:0 3px 8px;font-size:9px}.game-frame{border-width:5px;border-radius:8px;box-shadow:0 5px 0 #254b3e,0 10px 20px #506e5125}.world-footer{padding-top:11px}.objective-icon{width:25px;height:25px}.bottom-bar{height:35px;font-size:7px}.footer-tip{display:none}.mobile-controls{position:fixed;z-index:5;bottom:max(15px,env(safe-area-inset-bottom));left:0;right:0;height:110px;display:flex;align-items:center;justify-content:space-between;padding:0 29px;pointer-events:none}.dpad{width:120px;height:100px;position:relative;pointer-events:auto}.dpad button,.action-pad{touch-action:none;-webkit-tap-highlight-color:transparent;user-select:none;border:1px solid #b9cbb5;background:#f5f6e9eF;color:#547a62;box-shadow:0 4px 0 #bdcdb8;border-radius:10px;display:grid;place-items:center}.dpad button{position:absolute;width:39px;height:34px;font-size:13px}.dpad button:active,.action-pad:active{transform:translateY(3px);box-shadow:0 1px 0 #bdcdb8;background:#e3edcf}.dpad [data-dir=up]{top:0;left:40px}.dpad [data-dir=left]{top:34px;left:0}.dpad [data-dir=down]{top:34px;left:40px}.dpad [data-dir=right]{top:34px;left:80px}.action-pad{width:67px;height:67px;border-radius:50%;pointer-events:auto;background:#dcebc7;border-color:#aec69e;color:#477650;box-shadow:0 5px 0 #b0c5a4}.action-pad span{font-size:20px;line-height:20px}.action-pad small{font:7px 'DM Mono',monospace;letter-spacing:.6px;margin-top:-5px}.toast{bottom:8px;font-size:7px;padding:7px 10px}.battle-overlay{padding:9px 10px}.battle-top{padding:6px 8px}.battle-top strong{font-size:8px}.battle-message{bottom:57px;min-height:27px;padding:6px 7px;font-size:7px}.battle-actions{bottom:9px;left:9px;right:9px;gap:5px}.battle-btn{min-height:31px;font-size:7px}.battle-btn span{font-size:11px}.continue-btn{bottom:8px}.game-layout{padding-bottom:128px}}
@media(max-width:380px){.app-shell{padding:0 10px}.mobile-controls{padding:0 22px}.game-layout{padding-top:7px}.bottom-bar{font-size:6px}.battle-overlay{padding:7px}.battle-message{bottom:53px}.battle-btn{min-height:28px}.battle-actions{gap:3px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const battleCanvas = document.getElementById('battle-art');
  const bctx = battleCanvas.getContext('2d');
  bctx.imageSmoothingEnabled = false;
  const W = 22, H = 16, T = 16;
  const player = { x: 8, y: 8, face: 'down', step: 0 };
  const species = [
    { name:'Mosskin', type:'leaf', color:'#76a85f', dark:'#416d53', light:'#c7dc83', hp:24, icon:'☘' },
    { name:'Embercub', type:'fire', color:'#e98956', dark:'#a64d46', light:'#ffd184', hp:22, icon:'✦' },
    { name:'Dewdrop', type:'water', color:'#6aabd0', dark:'#49739e', light:'#c5e8e1', hp:20, icon:'◆' },
    { name:'Pufflet', type:'air', color:'#c7a6ce', dark:'#826d9d', light:'#f3d9bd', hp:18, icon:'✿' }
  ];
  const saved = (() => { try { return JSON.parse(localStorage.getItem('wildbound-save') || '{}'); } catch { return {}; } })();
  let party = Array.isArray(saved.party) && saved.party.length ? saved.party : [{ name:'Mosskin', level:3, xp:0, hp:24, maxHp:24, type:'leaf' }];
  let capsules = Number.isFinite(saved.capsules) ? saved.capsules : 3;
  let caughtCount = Math.max(0, party.length - 1);
  let battle = null;
  let moving = false, moveTimer = null, encounterSteps = 0;
  let toastTimer;
  const ui = {
    overlay:document.getElementById('battle-overlay'), name:document.getElementById('wild-name'), level:document.getElementById('wild-level'), hpText:document.getElementById('wild-hp-text'), hpFill:document.getElementById('wild-hp-fill'), message:document.getElementById('battle-message'), actions:document.getElementById('battle-actions'), continue:document.getElementById('continue-btn'), goal:document.getElementById('goal-text'), toast:document.getElementById('toast')
  };
  function save() { try { localStorage.setItem('wildbound-save', JSON.stringify({ party, capsules })); } catch {} }
  function hash(x,y){ let n=(x*374761393+y*668265263)|0;n=(n^(n>>>13))*1274126177;return (n^(n>>>16))>>>0; }
  function grassPatch(x,y){ return (x>3&&x<8&&y>3&&y<8)||(x>13&&x<19&&y>2&&y<7)||(x>11&&x<17&&y>10&&y<14)||(x>1&&x<5&&y>11&&y<15); }
  function pathTile(x,y){ return Math.abs(y-(10+Math.round(Math.sin(x*.31)*2)))<=1 || (x>=6&&x<=9&&y>=7&&y<=11) || (x>=15&&x<=17&&y>=6&&y<=11); }
  function tile(x,y){
    if(x<0||y<0||x>=W||y>=H)return 'edge';
    if((x>16&&x<21&&y>1&&y<6)||(x>17&&x<20&&y>5&&y<8))return 'water';
    if(pathTile(x,y))return 'path';
    if(grassPatch(x,y))return 'tall';
    if((hash(x,y)%100)<12 && !((x>6&&x<10)&&(y>7&&y<11))) return 'tree';
    return 'ground';
  }
  function fill(c,x,y,w,h){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
  function drawTile(type,sx,sy,wx,wy){
    const n=hash(wx,wy);
    if(type==='ground'||type==='edge'){
      fill((n%5===0)?'#9fc878':'#a7ce7e',sx,sy,16,16);
      if(n%4===0)fill('#8fbb72',sx+((n>>4)%12),sy+((n>>8)%12),2,2);
      if(n%7===0){fill('#d4df8a',sx+4,sy+10,2,2);fill('#85ad6b',sx+7,sy+11,2,2)}
      if(type==='edge')fill('#709c69',sx,sy,16,16);
    } else if(type==='path'){
      fill('#d6c58e',sx,sy,16,16);fill('#c8b47d',sx,sy+14,16,2);
      if(n%3===0)fill('#e5d39a',sx+(n%11),sy+5,3,2);
      if(n%4===1)fill('#b9a875',sx+10,sy+10,2,2);
    } else if(type==='tall'){
      fill('#9fc878',sx,sy,16,16);
      const shift=(n%4);
      fill('#50865c',sx+2,sy+9,3,6);fill('#6d9d62',sx+1,sy+6+shift,2,5);
      fill('#4b8055',sx+8,sy+8,3,7);fill('#79a95f',sx+9,sy+4+(shift>>1),2,6);
      fill('#56895a',sx+13,sy+10,2,5);fill('#c1d77d',sx+3,sy+7,1,2);
      fill('#b4d379',sx+10,sy+5,1,2);
    } else if(type==='water'){
      fill('#72b4bb',sx,sy,16,16);fill('#6aa7b0',sx,sy+13,16,3);
      if((n&1)===0){fill('#a5d6c8',sx+3,sy+4,5,2);fill('#8ac8c0',sx+10,sy+10,4,1)}else{fill('#a5d6c8',sx+8,sy+5,5,2);fill('#8ac8c0',sx+2,sy+11,4,1)}
    } else if(type==='tree'){
      fill('#9fc878',sx,sy,16,16);fill('#806848',sx+7,sy+10,4,6);fill('#477252',sx+3,sy+5,10,8);fill('#54845b',sx+5,sy+2,7,8);fill('#729c5d',sx+7,sy+3,3,3);fill('#3c684f',sx+2,sy+9,3,3);
    }
  }
  function drawPlayer(x,y){
    const bob=(player.step%2===0)?0:1;
    // soft little shadow
    fill('#628c5b88',x+3,y+15,10,3);
    // hair and face
    fill('#584b43',x+4,y+2+bob,8,4);fill('#6b5545',x+3,y+4+bob,10,4);
    fill('#e8b88b',x+4,y+5+bob,8,6);fill('#574840',x+5,y+7+bob,1,2);fill('#574840',x+10,y+7+bob,1,2);
    // cap
    fill('#e6c46f',x+3,y+1+bob,10,3);fill('#d79b5a',x+5,y,6,2);
    // jacket, scarf, arms
    fill('#e9eee0',x+3,y+10+bob,10,2);fill('#4d8065',x+4,y+11+bob,8,5);fill('#d8a85e',x+7,y+11+bob,3,2);
    fill('#e8b88b',x+2,y+12+bob,2,4);fill('#e8b88b',x+12,y+12+bob,2,4);
    fill('#5a5547',x+4,y+16+bob,3,2);fill('#5a5547',x+9,y+16+bob,3,2);
    if(player.face==='left')fill('#403d37',x+4,y+7+bob,1,2);if(player.face==='right')fill('#403d37',x+11,y+7+bob,1,2);
  }
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    let ox=Math.max(0,Math.min(W*16-canvas.width,player.x*16+8-canvas.width/2));
    let oy=Math.max(0,Math.min(H*16-canvas.height,player.y*16+8-canvas.height/2));
    // world itself is exactly canvas size, render a fixed viewport around the character
    ox=Math.max(0,Math.min(W*16-canvas.width,player.x*16+8-canvas.width/2));
    oy=Math.max(0,Math.min(H*16-canvas.height,player.y*16+8-canvas.height/2));
    for(let sy=0;sy<canvas.height;sy+=16)for(let sx=0;sx<canvas.width;sx+=16){let wx=Math.floor((sx+ox)/16),wy=Math.floor((sy+oy)/16);drawTile(tile(wx,wy),sx-(ox%16),sy-(oy%16),wx,wy)}
    // landmarks
    const houseX=8*16-ox,houseY=4*16-oy;
    if(houseX>-35&&houseX<canvas.width&&houseY>-42&&houseY<canvas.height){fill('#a95f4e',houseX,houseY+9,32,22);fill('#754e43',houseX+4,houseY+17,24,14);fill('#d79a68',houseX+2,houseY+6,28,8);fill('#e6c581',houseX+7,houseY+22,6,9);fill('#a9c5b2',houseX+19,houseY+19,6,6);fill('#784b42',houseX+14,houseY+1,4,9)}
    const signX=10*16-ox,signY=5*16-oy;if(signX>-20&&signX<canvas.width&&signY>-20&&signY<canvas.height){fill('#79583c',signX+7,signY+5,2,10);fill('#f0d99a',signX+2,signY+2,12,7);fill('#9a8151',signX+4,signY+4,7,1)}
    const px=player.x*16-ox,py=player.y*16-oy;drawPlayer(px,py);
    document.getElementById('coords').textContent=String(player.x).padStart(2,'0')+' · '+String(player.y).padStart(2,'0');
    requestAnimationFrame(draw);
  }
  function showToast(text){ui.toast.textContent=text;ui.toast.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.style.opacity='0',2600)}
  function drawCreature(mon){
    bctx.clearRect(0,0,144,112); const c=mon.color,d=mon.dark,l=mon.light;
    bctx.fillStyle='#72975c55';bctx.fillRect(43,91,60,8);
    const p=(x,y,w,h,col)=>{bctx.fillStyle=col;bctx.fillRect(x*4,y*4,w*4,h*4)};
    if(mon.type==='leaf'){
      p(8,9,8,8,d);p(9,8,7,9,c);p(11,5,4,5,'#4c8456');p(12,2,2,5,'#79aa5b');p(14,3,4,2,'#8ebd65');p(13,1,3,3,l);p(8,12,2,3,l);p(15,13,1,2,'#ebd7a2');
    } else if(mon.type==='fire'){
      p(7,9,10,7,d);p(8,7,8,9,c);p(9,5,6,4,'#e99a61');p(6,5,3,4,d);p(6,3,3,4,'#f3b662');p(11,3,2,4,'#e4b46a');p(14,13,4,2,'#f4a35c');p(15,12,3,2,'#ffe09a');
    } else if(mon.type==='water'){
      p(8,7,8,10,d);p(7,8,10,7,c);p(9,5,6,4,c);p(10,3,4,3,l);p(5,9,3,3,'#83c2d1');p(16,10,3,3,'#83c2d1');p(11,13,2,2,l);
    } else {
      p(7,9,10,7,d);p(8,7,8,9,c);p(6,5,4,5,l);p(12,5,5,5,l);p(9,4,5,5,c);p(10,8,1,2,'#57475c');p(14,8,1,2,'#57475c');p(10,14,4,1,d);
    }
    // sparkles
    p(3,5,1,1,'#fff3c1');p(20,8,1,1,'#fff3c1');p(18,3,1,1,'#fff3c1');
  }
  function updateParty(){
    const list=document.getElementById('party-list');list.innerHTML='';
    party.forEach((m,i)=>{const sp=species.find(s=>s.name===m.name)||species[0];const row=document.createElement('div');row.className='party-slot';row.innerHTML=`<div class="mini-mon" style="color:${sp.dark}">${sp.icon}</div><div><div class="party-name">${m.name}</div><div class="party-lv">LV. ${m.level||3} · ${i===0?'TRAIL PARTNER':'NEW FRIEND'}</div></div><div class="party-hp"><i style="width:${Math.max(0,(m.hp||m.maxHp||20)/(m.maxHp||20)*100)}%"></i></div>`;list.appendChild(row)});
    document.getElementById('team-count').textContent=String(party.length).padStart(2,'0')+' / 06';
    document.getElementById('capsule-count').textContent=capsules;document.getElementById('capsule-display').textContent=String(capsules).padStart(2,'0');
    document.getElementById('guide-count').textContent=Math.min(caughtCount,3)+' / 3';document.getElementById('guide-progress').style.width=Math.min(100,caughtCount/3*100)+'%';
  }
  function setBattleMessage(text){ui.message.textContent=text}
  function updateHp(){if(!battle)return;const pct=Math.max(0,battle.hp/battle.maxHp*100);ui.hpText.textContent=`${Math.max(0,battle.hp)} / ${battle.maxHp}`;ui.hpFill.style.width=pct+'%';ui.hpFill.className=pct<25?'critical':pct<50?'low':''}
  function beginBattle(){
    const options=species.filter(s=>!party.some(p=>p.name===s.name));const sp=options[Math.floor(Math.random()*options.length)]||species[1];
    const lv=2+Math.floor(Math.random()*3);battle={name:sp.name,type:sp.type,color:sp.color,dark:sp.dark,light:sp.light,icon:sp.icon,level:lv,maxHp:sp.hp+lv*2,hp:sp.hp+lv*2};
    ui.name.textContent=battle.name;ui.level.textContent='LV. '+lv;ui.overlay.classList.remove('hidden');ui.actions.classList.remove('hidden');ui.continue.classList.add('hidden');setBattleMessage(`A wild ${battle.name} appeared!`);drawCreature(battle);updateHp();
  }
  function endBattle(text,goal){setBattleMessage(text);ui.actions.classList.add('hidden');ui.continue.classList.remove('hidden');if(goal)ui.goal.textContent=goal;}
  function wildTurn(){if(!battle)return;const dmg=2+Math.floor(Math.random()*4);const lead=party[0];lead.hp=Math.max(0,(lead.hp??lead.maxHp??24)-dmg);if(lead.hp===0)lead.hp=lead.maxHp||24;updateParty();setBattleMessage(`${battle.name} nudged ${lead.name}! It’s still eager to explore.`)}
  function attack(){if(!battle)return;const dmg=5+Math.floor(Math.random()*6)+(party[0].level||3);battle.hp=Math.max(0,battle.hp-dmg);updateHp();if(battle.hp===0){const lead=party[0];lead.xp=(lead.xp||0)+1;if(lead.xp>=3){lead.xp=0;lead.level=(lead.level||3)+1}updateParty();save();endBattle(`${battle.name} is ready to rest. ${lead.name} gained a little experience!`,'Keep exploring the meadow');return}setBattleMessage(`${party[0].name} used Spark! ${battle.name} is looking a little tired.`);setTimeout(wildTurn,650)}
  function catchCreature(){if(!battle)return;if(capsules<=0){setBattleMessage('You are out of capsules. Maybe visit Nana Willow!');return}if(party.length>=6){setBattleMessage('Your team is full. There is room for six friends.');return}capsules--;updateParty();const chance=.35+(1-battle.hp/battle.maxHp)*.5;const captured=Math.random()<chance;const name=battle.name;if(captured){party.push({name,level:battle.level,xp:0,hp:battle.maxHp,maxHp:battle.maxHp,type:battle.type});caughtCount++;updateParty();save();endBattle(`${name} joined your team! What a lovely new friend.`,'Find another friendly creature');return}setBattleMessage(`${name} wiggled free! It looks a little more tired now.`);setTimeout(()=>{if(battle){battle.hp=Math.max(1,battle.hp-3);updateHp();wildTurn()}},650)}
  function runAway(){if(!battle)return;endBattle(`You waved goodbye to ${battle.name} and continued along the trail.`,'Explore the tall grass')}
  document.getElementById('attack-btn').addEventListener('click',attack);document.getElementById('catch-btn').addEventListener('click',catchCreature);document.getElementById('run-btn').addEventListener('click',runAway);
  ui.continue.addEventListener('click',()=>{battle=null;ui.overlay.classList.add('hidden');encounterSteps=0;showToast('The meadow breeze carries you onward…')});
  function tryMove(dir){if(battle)return;let dx=0,dy=0;if(dir==='up'){dy=-1;player.face='up'}if(dir==='down'){dy=1;player.face='down'}if(dir==='left'){dx=-1;player.face='left'}if(dir==='right'){dx=1;player.face='right'}const nx=player.x+dx,ny=player.y+dy;const typ=tile(nx,ny);if(typ==='tree'||typ==='water'||typ==='edge'){showToast(typ==='water'?'The pond is too deep to cross.':'A sturdy tree blocks the way.');return}player.x=nx;player.y=ny;player.step++;if(typ==='tall'){encounterSteps++;if(encounterSteps>2&&Math.random()<.17){beginBattle();return}}if(encounterSteps>=6&&typ!=='tall')encounterSteps=3;}
  function action(){if(battle)return;let nx=player.x,ny=player.y;if(player.face==='up')ny--;if(player.face==='down')ny++;if(player.face==='left')nx--;if(player.face==='right')nx++;if(nx===10&&ny===5){capsules=Math.min(9,capsules+2);updateParty();save();showToast('Nana Willow left two capsules by the trail sign!');return}if(nx===8&&ny===4){showToast('Nana Willow’s cottage. She’s out gathering herbs today.');return}showToast('The grass whispers softly. Keep exploring to meet a new friend!')}
  const held=new Set();function keyDown(e){const k=e.key.toLowerCase();const dirs={arrowup:'up',w:'up',arrowdown:'down',s:'down',arrowleft:'left',a:'left',arrowright:'right',d:'right'};if(dirs[k]){e.preventDefault();if(!held.has(k)){held.add(k);tryMove(dirs[k]);moveTimer=setInterval(()=>tryMove(dirs[k]),190)}return}if(k===' '||k==='enter'){e.preventDefault();action()}}
  function keyUp(e){const k=e.key.toLowerCase();if(held.has(k)){held.delete(k);clearInterval(moveTimer)}}window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>{held.clear();clearInterval(moveTimer)});
  document.querySelectorAll('.dpad button').forEach(btn=>{const dir=btn.dataset.dir;let timer;const stop=e=>{e.preventDefault();clearInterval(timer)};btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);tryMove(dir);timer=setInterval(()=>tryMove(dir),190)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,stop))});document.getElementById('touch-action').addEventListener('pointerdown',e=>{e.preventDefault();action()});
  let soundOn=false;document.getElementById('sound-toggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';showToast(soundOn?'Birdsong is on.':'Sound muted.')});
  updateParty();if(caughtCount>0)ui.goal.textContent='Find another friendly creature';requestAnimationFrame(draw);
})();

